import sys
from typing import List

class UnionFind:
    def __init__(self, n):
        self.parent = list(range(n))

    def find(self, u):
        if self.parent[u] != u:
            self.parent[u] = self.find(self.parent[u])
        return self.parent[u]

    def union(self, u, v):
        pu, pv = self.find(u), self.find(v)
        if pu != pv:
            self.parent[pu] = pv

def min_tunnel_cost(N: int, planets: List[List[int]]) -> int:
    edges = []
    for i in range(N):
        for j in range(i + 1, N):
            dx, dy, dz = abs(planets[i][0] - planets[j][0]), abs(planets[i][1] - planets[j][1]), abs(planets[i][2] - planets[j][2])
            edges.append((min(dx, dy, dz), i, j))

    edges.sort()
    uf = UnionFind(N)
    total_cost = 0
    for cost, u, v in edges:
        if uf.find(u) != uf.find(v):
            uf.union(u, v)
            total_cost += cost

    return total_cost

